92:         })?;
93:         if !parent.is_dir() {
94:             return Err(DhError::InvalidInput(format!(
95:                 "project parent is not a directory: '{}'",
96:                 parent.display()
97:             )));
98:         }
99: 
100:         // Read and validate private state before creating any project files.
101:         let mut index = self.load_index()?;
102:         let project_directory = parent.join(&name);
103:         fs::create_dir(&project_directory).map_err(|error| {
104:             DhError::State(format!(
105:                 "cannot create project directory '{}': {error}",
106:                 project_directory.display()
107:             ))
108:         })?;
109: 
110:         let workbook_file_name = if name.to_ascii_lowercase().ends_with(".xlsx") {
111:             name.clone()
112:         } else {
