                Screen::ProjectWorkspace,
                Action::CreateProject,
                form("Report", "/tmp")
            ),
            Availability::Hidden
        );
    }

    #[test]
    fn pdf_import_is_disabled_with_an_explanation_in_the_workspace() {
        let availability = availability(
            Screen::ProjectWorkspace,
            Action::ImportPdf,
            form("Report", "/tmp"),
        );
        assert_eq!(availability, Availability::Disabled(NOT_AVAILABLE_YET));
        assert!(!NOT_AVAILABLE_YET.is_empty());
    }

    #[test]
    fn pdf_import_is_not_offered_on_project_home() {
        assert_eq!(
            availability(Screen::ProjectHome, Action::ImportPdf, form("", "")),
            Availability::Hidden
        );
