import json, subprocess, re, sys

meta = json.loads(subprocess.check_output(["cargo", "metadata", "--format-version", "1"], cwd="/home/mozaff/Documents/GitHub/Document-Harvester"))
pkgs = {(p["name"], p["version"]): p for p in meta["packages"]}

def load(path):
    out = []
    for line in open(path):
        m = re.match(r"^([^ ]+) v([^ ]+)$", line.strip())
        if m:
            out.append((m.group(1), m.group(2)))
    return sorted(set(out))

def known(tok):
    t = tok.strip().upper()
    return t in {
        "MIT", "MIT-0", "APACHE-2.0", "BSD-2-CLAUSE", "BSD-3-CLAUSE", "BSD-4-CLAUSE",
        "ISC", "ZLIB", "0BSD", "UNLICENSE", "CC0-1.0", "UNICODE-3.0", "BSL-1.0",
        "MPL-2.0", "CDDL-1.0",
    }

def category(lic):
    if not lic:
        return "MISSING"
    if "LicenseRef-" in lic:
        return "CUSTOM-ID"
    toks = [x.strip() for x in re.split(r"/| OR | AND |\(|\)", lic) if x.strip()]
    knowns = [x for x in toks if known(x)]
    others = [x for x in toks if not known(x)]
    if any(x.upper().startswith("GPL") or "GPL" in x.upper() for x in toks):
        if "OR" in lic and knowns:
            return "MULTI-WITH-GPL-OPTION"
        return "COPYLEFT"
    if others:
        return "UNRECOGNIZED"
    if len(knowns) > 1:
        return "MULTI-PERMISSIVE"
    return "PERMISSIVE"

for title, path in [("RUNTIME (dh-app normal, host target)", "/tmp/opencode/runtime.txt"),
                    ("DEV-ONLY (workspace dev edges minus runtime)", "/tmp/opencode/dev_only.txt")]:
    ids = load(path)
    print(f"## {title}: {len(ids)} packages")
    cats = {}
    flagged = []
    for name, ver in ids:
        p = pkgs.get((name, ver))
        if not p:
            print(f"!! not in metadata: {name} {ver}")
            continue
        lic = p.get("license") or ""
        lf = p.get("license_file") or ""
        cat = category(lic)
        cats[cat] = cats.get(cat, 0) + 1
        if cat not in ("PERMISSIVE", "MULTI-PERMISSIVE"):
            flagged.append(f"{name} {ver} | {lic or '(no license field)'} | license_file={lf or '(none)'} | {cat}")
    print("CATEGORIES:", cats)
    print("FLAGGED:")
    for f in flagged:
        print("  " + f)
    print()

# system libraries / native requirements
print("## -sys / native / binary packages")
for title, path in [("runtime", "/tmp/opencode/runtime.txt"), ("dev-only", "/tmp/opencode/dev_only.txt")]:
    for name, ver in load(path):
        if "-sys" in name or name in ("cc", "pkg-config", "cmake", "vcpkg", "num_jobs", "windows-link", "winapi", "windows-sys", "windows-targets"):
            print(f"{title}: {name} {ver}")

